import{o as i,c as t,ak as h,bi as a}from"./chunks/framework.3a0Z_LB9.js";const g=JSON.parse('{"title":"Khởi tạo dữ liệu","description":"","frontmatter":{"prev":{"text":"Bán hàng xuất khẩu","link":"/TT99/ban-hang-xuat-khau"},"next":{"text":"Bán hàng đại lý bán đúng giá - Tiền mặt","link":"/TT99/ban-hang-dai-ly-ban-dung-gia-tien-mat"}},"headers":[],"relativePath":"TT99/001-khoi-tao-du-lieu.md","filePath":"TT99/001-khoi-tao-du-lieu.md"}'),l={name:"TT99/001-khoi-tao-du-lieu.md"},c=Object.assign(l,{setup(u){return(o,n)=>(i(),t("div",null,[...n[0]||(n[0]=[h('<h1 id="khoi-tao-du-lieu" tabindex="-1">Khởi tạo dữ liệu <a class="header-anchor" href="#khoi-tao-du-lieu" aria-label="Permalink to “Khởi tạo dữ liệu”">​</a></h1><p>Khác với các phần mềm hiện có trên thị trường, Phần mềm kế toán chuyên sâu BKIT giải quyết triệt để vấn để Nhiều năm tài chính trên cùng 1 dữ liệu kế toán. Giả sử Nếu một phần mềm kế toán không hỗ trợ nhiều năm tài chính sẽ gặp nhược điểm với:</p><ul><li>So sánh yoy (year over year)</li><li>Dự báo dựa theo dữ liệu quá khứ</li><li>Nhập, xuất dữ liệu (khách hàng, nhà cung cấp, hàng hóa, dịch vụ, v.v..) giữa các năm tài chính rất nhiêu khê và dễ lỗi.</li></ul><p><img src="'+a+'" alt="org.jpg"></p><h1 id="luong-tu-phuc-vu" tabindex="-1">Luồng tự phục vụ <a class="header-anchor" href="#luong-tu-phuc-vu" aria-label="Permalink to “Luồng tự phục vụ”">​</a></h1><p>Thứ tự khởi tạo: Với người dùng đầu tiên của 1 công ty.</p><ul><li>Người dùng tự đăng ký tài khoản tại <a href="https://a.bkit.vn" target="_blank" rel="noreferrer">https://a.bkit.vn</a></li><li>Người dùng tự cấu hình OTP (One time password) trên điện thoại di động.</li><li>Người dùng đầu tiên của 1 công ty khởi tạo dữ liệu kế toán</li></ul><p>Thứ tự khởi tạo: Với người dùng thứ 2 trở đi của 1 công ty.</p><ul><li>Người dùng tự đăng ký tài khoản tại <a href="https://a.bkit.vn" target="_blank" rel="noreferrer">https://a.bkit.vn</a></li><li>Người dùng tự cấu hình OTP (One time password) trên điện thoại di động.</li><li>Yêu cầu người dùng đầu tiên của công ty gửi email và cấp mã mời vào công ty</li><li>Người dùng thứ 2 trở đi của 1 công ty nhìn thấy dữ liệu kế toán</li></ul><h1 id="luong-khoi-tao-du-lieu-ke-toan" tabindex="-1">Luồng khởi tạo Dữ liệu kế toán: <a class="header-anchor" href="#luong-khoi-tao-du-lieu-ke-toan" aria-label="Permalink to “Luồng khởi tạo Dữ liệu kế toán:”">​</a></h1><ul><li>Khởi tạo công ty mẹ, công ty con , chi nhánh, phòng ban nếu có.</li><li>Khởi tạo Năm tài chính</li><li>Khai báo Khách hàng</li><li>Khai báo Nhà cung cấp</li><li>Khai báo Nhân viên</li><li>Khai báo cơ quan chính phủ có mối quan hệ liên quan, ví dụ cơ quan thuế</li><li>Khai báo thông tin Đại lý thuế nếu có</li></ul><h1 id="luong-nho-bkit-phuc-vu" tabindex="-1">Luồng nhờ BKIT phục vụ <a class="header-anchor" href="#luong-nho-bkit-phuc-vu" aria-label="Permalink to “Luồng nhờ BKIT phục vụ”">​</a></h1><p>Ngoài ra, Quý khách có thể yêu cầu phía BKIT khởi tạo các thông tin này, cài đặt chuẩn bị hệ thống để tránh các logic phức tạp, và đi sớm vào chuyên môn kế toán của mình.</p><h1 id="bkit-lang-nghe-phan-hoi-tu-nguoi-dung" tabindex="-1">BKIT lắng nghe phản hồi từ người dùng <a class="header-anchor" href="#bkit-lang-nghe-phan-hoi-tu-nguoi-dung" aria-label="Permalink to “BKIT lắng nghe phản hồi từ người dùng”">​</a></h1><p>Nếu quý khách có sáng tạo được luồng khởi tạo tốt hơn, vui lòng chia sẻ và cho chúng tôi biết qua email <a href="mailto:info@bkit.vn" target="_blank" rel="noreferrer">info@bkit.vn</a> .</p><p>Cập nhật lúc 14:58 Thứ Ba, 9 tháng 6, 2026 (GMT+7)</p>',16)])]))}});export{g as __pageData,c as default};
